export type Job = {
  id: string;
  title: string;
  dept: string;
  location: string;
  type: string;
  salary: string;
  posted: string;
};

export type Department = {
  id: string;
  name: string;
};

export type JobLabels = {
  apply: string;
  caption: string;
  role: string;
  team: string;
  location: string;
  type: string;
  salary: string;
  count: string;
};
